"""tools/brain/voice_gate.py — the mouth-voices-the-brain bench's grader.

Marks (the law §3): I1 (the plain-genome replays' own exits + the lean OFF journals against the DRIVE gate's sealed B-ON
journals + the DELTA plant's exit), I2 (ON minus voice rows = OFF, the brain's saved state, the frame rows), V (a voice row
is its turn's say, field by field, iff the turn said, between the turn and learn rows), T (every voiced word a true word of
the thing under it, ≥ 0.95 per lean life and pooled, above every one of ≥ 100 dealt-phrase draws substream(SEED,
"voice-null:<k>"); the pooled null is the pool of the three lives' own named draws), C (voice rate ≥ 0.85 in every
1,000-canvas window after the first calibration), Z (the constant mouth reads FAIL), F (the frame mouth unmoved on the full
life: its say rows, said/heard_yes/heard_no, frames filed, and state/predictions.jsonl byte-equal), K (the mind's CPU per
canvas ON over OFF ≤ 1.05), R-FRAME (the frame mouth's says read by the SAME key — both words true of ONE thing in view —
paired with the voices where a canvas has both, the smallest passing gap 10/n beside it; a reading, no bar).
Controls (§3, each asserts it changed the bytes): the wrong voice, the ECHO (T passes, V fails; the coincidence share
printed, NOTE-2), the planted say (T 0.000), the silent mouth (T NOT GRADABLE, never a pass; C 0), the missing and the
orphan voice, the order swap, the DELTA identity plant of I1.
Unit-tested on a fake two-thing world (tests/tools/test_voice_gate.py); the bench drives main()."""
from __future__ import annotations

import argparse
import collections
import json
import re
import sys
from pathlib import Path
from typing import Dict, List, Optional, Tuple

import numpy as np

ROOT = Path(__file__).resolve().parents[2]
if str(ROOT) not in sys.path:
    sys.path.insert(0, str(ROOT))

from brain.scene import learners as Lr      # noqa: E402
from brain.scene import marks as M          # noqa: E402
from brain.scene import world as W          # noqa: E402
from brain.world.seeds import substream     # noqa: E402

T_BAR = 0.95
C_BAR = 0.85
K_BAR = 1.05
NULL_DRAWS = 100
_KINDS = [list(W.SHAPES), list(W.COLOUR_NAMES), list(W.SIZE_NAMES)]


# -------------------------------------------------------------------------------- the rows
def rows_of(p: Path) -> List[Dict[str, object]]:
    return [json.loads(line) for line in Path(p).read_text().splitlines() if line.strip()]


def canon(r: Dict[str, object]) -> str:
    return json.dumps(r, sort_keys=True)


def is_turn(r: Dict[str, object]) -> bool:
    return r.get("kind") == "brain" and r.get("act") == "turn"


def is_voice(r: Dict[str, object]) -> bool:
    return r.get("kind") == "brain" and r.get("act") == "voice"


def is_learn(r: Dict[str, object]) -> bool:
    return r.get("kind") == "brain" and r.get("act") == "learn"


def is_frame_say(r: Dict[str, object]) -> bool:
    """The cells' frame mouth's own row: a bare {seq, say:{frame, heard, episodes}} — no kind/act (a brain row) and the
    frame key (a chat's say row carries none)."""
    return "kind" not in r and isinstance(r.get("say"), dict) and "frame" in r["say"]


def compare_rows(a: List[Dict[str, object]], b: List[Dict[str, object]]) -> Optional[Dict[str, object]]:
    for k, (x, y) in enumerate(zip(a, b)):
        if canon(x) != canon(y):
            return {"row": k, "seq": x.get("seq"), "a": canon(x)[:200], "b": canon(y)[:200]}
    if len(a) != len(b):
        return {"row": min(len(a), len(b)), "seq": None, "length_a": len(a), "length_b": len(b)}
    return None


# -------------------------------------------------------------------------------- the truth (the generator's own specs, never a cache)
def canvas_key(row: Dict[str, object]) -> Tuple[int, int]:
    """(world_seed, scene) of a brain row: the extra keys when the hand is not the scene world (HEARS-2), else the moment."""
    if row.get("world_seed") is not None and row.get("scene") is not None:
        return int(row["world_seed"]), int(row["scene"])
    m = re.fullmatch(r"sc(\d+)t(\d+)", str(row.get("moment")))
    if not m:
        raise ValueError(f"no canvas key on row {row!r}")
    return int(m.group(1)), int(m.group(2))


def true_words(thing: Dict[str, object]) -> set:
    return {str(thing["shape"]), str(thing["colour"]), str(thing["size"])}


def scene_spec(ws: int, scene: int) -> Dict[str, object]:
    """The scene world's own spec, REGENERATED by its generator from (world_seed, scene) — PREREG-BRAIN-DRIVES' bench's
    truth for its S mark, read the same way; never a cache (the machinery pin's redraw is the seat's window)."""
    s = W.train_scene(int(ws), int(scene))
    return {"things": [t.to_dict() for t in s.things], "words": list(s.words), "referent": s.referent}


def labels_of(members, fix, things) -> Tuple[List[Optional[int]], List[Optional[int]]]:
    """Per hypothesis, the thing under most of its fixations (the seat probe's own rule): fix_thing per fixation cell,
    then marks.hyp_label over marks.hyp_counts."""
    tt = M.things_of({"things": things})
    fix_thing = [W.fixation_thing((int(c[0]), int(c[1])), tt) for c in fix]
    return [M.hyp_label(c) for c in M.hyp_counts(members, fix_thing)], fix_thing


def _voice_grades(rows: List[Dict[str, object]], truth) -> List[Dict[str, object]]:
    """Per voice row: its canvas's spec, its say's hypothesis's label, and whether every word is a true word of the thing
    under it. tw None (no thing under the target) → counted not-graded by the caller (the probe's own rule)."""
    turns = {int(r["seq"]): r for r in rows if is_turn(r)}
    learns = {int(r["seq"]): r for r in rows if is_learn(r)}
    out: List[Dict[str, object]] = []
    for r in rows:
        if not is_voice(r):
            continue
        t, l = turns.get(int(r["seq"])), learns.get(int(r["seq"]))
        if t is None or l is None:
            out.append({"seq": int(r["seq"]), "words": [str(w) for w in r["say"]["words"]], "label": None, "tw": None,
                        "true": None, "key": None})
            continue
        ws, scene = canvas_key(r)
        spec = truth(ws, scene)
        labels, _ft = labels_of(t["members"], l["fix"], spec["things"])
        h = int(r["say"]["hyp"])
        lab = labels[h] if 0 <= h < len(labels) else None
        words = [str(w) for w in r["say"]["words"]]
        tw = true_words(spec["things"][lab]) if lab is not None else None
        out.append({"seq": int(r["seq"]), "key": (ws, scene), "words": words, "label": lab, "tw": tw,
                    "true": (all(w in tw for w in words) if tw is not None else None)})
    return out


# -------------------------------------------------------------------------------- V
def mark_v(rows: List[Dict[str, object]]) -> Dict[str, object]:
    turns = {int(r["seq"]): (k, r) for k, r in enumerate(rows) if is_turn(r)}
    learns = {int(r["seq"]): (k, r) for k, r in enumerate(rows) if is_learn(r)}
    voices = [(k, r) for k, r in enumerate(rows) if is_voice(r)]
    said = {s: (k, r) for s, (k, r) in turns.items() if r.get("say") is not None}
    first: Optional[Dict[str, object]] = None

    def fail(kind: str, r: Optional[Dict[str, object]], detail: str) -> None:
        nonlocal first
        if first is None:
            first = {"kind": kind, "seq": (r or {}).get("seq"), "detail": detail}

    for k, v in voices:
        t = turns.get(int(v["seq"]))
        if t is None:
            fail("orphan-voice", v, "a voice row without its turn row")
            continue
        tk, tr = t
        lk = learns.get(int(v["seq"]), (None, None))[0]
        if not (tk < k and (lk is None or k < lk)):
            fail("order", v, f"the voice does not sit between its turn (row {tk}) and its learn (row {lk}): row {k}")
        if tr.get("say") is None:
            fail("orphan-voice", v, "its turn said nothing")
        elif canon(v.get("say")) != canon(tr["say"]):
            fail("wrong-say", v, "the voice is not its turn's say, field by field")
    if len(voices) != len(said):
        vseqs = {int(v["seq"]) for _, v in voices}
        for s, (k, tr) in sorted(said.items()):
            if s not in vseqs:
                fail("missing-voice", tr, "a said turn without its voice row")
                break
        else:
            fail("missing-voice" if len(voices) < len(said) else "orphan-voice", None,
                 f"the counts differ: voice rows {len(voices)}, turns carrying a say {len(said)}")
    return {"pass": first is None, "rows_read": len(rows), "turns_with_say": len(said), "voice_rows": len(voices),
            "first_failure": first}


# -------------------------------------------------------------------------------- T (and its dealt-phrase null)
def mark_t(rows: List[Dict[str, object]], truth, seed: int, nulls: int = NULL_DRAWS, bar: float = T_BAR) -> Dict[str, object]:
    grades = _voice_grades(rows, truth)
    graded = [g for g in grades if g["tw"] is not None]
    not_graded = len(grades) - len(graded)
    if not graded:
        return {"verdict": "NOT GRADABLE", "pass": False, "true": None, "n": len(grades), "graded": 0,
                "not_graded": not_graded, "null_max": None, "null_draws": 0, "null_ok": [], "bar": bar}
    true = sum(bool(g["true"]) for g in graded) / len(graded)
    null_ok: List[int] = []
    if len(graded) > 1:
        for k in range(nulls):
            p = Lr.nshuf_permutation(substream(int(seed), f"voice-null:{k}"), len(graded))
            null_ok.append(sum(all(w in g["tw"] for w in graded[int(p[j])]["words"]) for j, g in enumerate(graded)))
    null_rate = [ok / len(graded) for ok in null_ok]
    null_max = max(null_rate) if null_rate else None
    return {"verdict": "GRADED", "pass": bool(true >= bar and (null_max is None or true > null_max)), "true": true,
            "n": len(grades), "graded": len(graded), "not_graded": not_graded, "null_max": null_max,
            "null_draws": len(null_rate), "null_ok": null_ok, "null": null_rate, "bar": bar}


def pooled_t(per_life: List[Dict[str, object]], bar: float = T_BAR) -> Dict[str, object]:
    """The lean lives pooled; the pooled dealt draw k = the pool of the three lives' OWN named draws k (no new substream)."""
    graded = sum(t["graded"] for t in per_life)
    if not graded:
        return {"verdict": "NOT GRADABLE", "pass": False, "graded": 0}
    true = sum(t["true"] * t["graded"] for t in per_life) / graded
    draws = max((len(t["null_ok"]) for t in per_life), default=0)
    pool = [sum((t["null_ok"][k] if k < len(t["null_ok"]) else 0) for t in per_life) / graded for k in range(draws)]
    null_max = max(pool) if pool else None
    return {"verdict": "GRADED", "pass": bool(true >= bar and (null_max is None or true > null_max)), "true": true,
            "graded": graded, "not_graded": sum(t["not_graded"] for t in per_life), "null_max": null_max,
            "null_draws": len(pool), "bar": bar}


# -------------------------------------------------------------------------------- C
def mark_c(rows: List[Dict[str, object]], window: int = 1000, bar: float = C_BAR) -> Dict[str, object]:
    turns = [r for r in rows if is_turn(r)]
    vseqs = {int(r["seq"]) for r in rows if is_voice(r)}

    def rate(rs) -> Tuple[Optional[float], int]:
        cal = [t for t in rs if t.get("reason") != "not calibrated" and int(t.get("n_hyp") or 0) > 0]
        return ((sum(int(t["seq"]) in vseqs for t in cal) / len(cal)) if cal else None), len(cal)

    series = []
    for s in range(0, len(turns), window):
        r, n = rate(turns[s:s + window])
        series.append({"from": s, "to": min(len(turns), s + window), "rate": r, "canvases": n})
    have = [w for w in series if w["rate"] is not None]
    low = min(have, key=lambda w: w["rate"]) if have else None
    overall, _n = rate(turns)
    return {"pass": bool(low is not None and low["rate"] >= bar), "lowest_window": low, "windows": len(series),
            "overall": overall, "bar": bar, "series": series}


# -------------------------------------------------------------------------------- Z
def mark_z(rows: List[Dict[str, object]], truth) -> Dict[str, object]:
    grades = [g for g in _voice_grades(rows, truth) if g["tw"] is not None]
    if not grades:
        return {"verdict": "NOT GRADABLE", "caught": False, "graded": 0}
    phrases = collections.Counter(tuple(g["words"]) for g in grades)
    phrase, modal_n = sorted(phrases.items(), key=lambda kv: (-kv[1], kv[0]))[0]
    const = sum(all(w in g["tw"] for w in phrase) for g in grades) / len(grades)
    return {"verdict": "GRADED", "phrase": list(phrase), "modal_n": modal_n, "graded": len(grades),
            "constant_true": const, "caught": bool(const < T_BAR),
            "note": "the dealt null is blind to a constant phrase (invariant under dealing): the absolute bar fails it"}


# -------------------------------------------------------------------------------- the plants (each asserts it changed the bytes)
def plant_wrong_voice(rows: List[Dict[str, object]], i: int) -> Tuple[List[Dict[str, object]], bool]:
    rows2 = json.loads(json.dumps(rows))
    vo = [k for k, r in enumerate(rows2) if is_voice(r)]
    a, b = vo[i], vo[(i + 1) % len(vo)]
    rows2[a]["say"], rows2[b]["say"] = rows2[b]["say"], rows2[a]["say"]
    return rows2, rows2 != rows


def plant_missing_voice(rows: List[Dict[str, object]], i: int) -> Tuple[List[Dict[str, object]], bool]:
    vo = [k for k, r in enumerate(rows) if is_voice(r)]
    rows2 = [r for k, r in enumerate(rows) if k != vo[i]]
    return rows2, rows2 != rows


def plant_orphan_voice(rows: List[Dict[str, object]], i: int) -> Tuple[List[Dict[str, object]], bool]:
    rows2 = json.loads(json.dumps(rows))
    vo = [k for k, r in enumerate(rows2) if is_voice(r)]
    dup = dict(rows2[vo[i]])
    dup["say"] = dict(rows2[vo[i]]["say"])
    dup["seq"] = max(int(r["seq"]) for r in rows2) + 1000
    rows2.append(dup)
    return rows2, rows2 != rows


def plant_order_swap(rows: List[Dict[str, object]], i: int) -> Tuple[List[Dict[str, object]], bool]:
    rows2 = list(rows)
    vo = [k for k, r in enumerate(rows2) if is_voice(r)]
    k = vo[i]
    assert is_learn(rows2[k + 1]), "the mind's own order: a voice row sits just before its learn row"
    rows2[k], rows2[k + 1] = rows2[k + 1], rows2[k]
    return rows2, rows2 != rows


def plant_silent(rows: List[Dict[str, object]]) -> Tuple[List[Dict[str, object]], bool]:
    rows2 = [r for r in rows if not is_voice(r)]
    return rows2, rows2 != rows


def plant_echo(rows: List[Dict[str, object]], truth) -> Tuple[List[Dict[str, object]], bool, Dict[str, object]]:
    """The ECHO (the law §3, control 2): a mouth that voices the HEARD words of the canvas, about the thing the parent
    named (the hypothesis labelled to the canvas's referent). T passes it (the parent speaks true sentences); V fails it.
    The coincidence share (NOTE-2): the voiced echoes whose heard words equal the brain's own say words."""
    rows2 = json.loads(json.dumps(rows))
    turns = {int(r["seq"]): r for r in rows2 if is_turn(r)}
    learns = {int(r["seq"]): r for r in rows2 if is_learn(r)}
    voiced = dropped = coincide = 0
    for r in rows2:
        if not is_voice(r):
            continue
        t, l = turns.get(int(r["seq"])), learns.get(int(r["seq"]))
        heard = [str(w) for w in (t.get("heard") or [])]
        labels, _ft = labels_of(t["members"], l["fix"], truth(*canvas_key(r))["things"])
        ref = truth(*canvas_key(r)).get("referent")
        h_ref = next((h for h, lab in enumerate(labels) if lab is not None and lab == ref), None)
        if h_ref is None or not heard:
            r["say"] = None      # the echo cannot name this canvas: dropped (counted, a presence)
            dropped += 1
            continue
        if heard == [str(w) for w in r["say"]["words"]]:
            coincide += 1
        r["say"] = {"hyp": h_ref, "fix": [int(x) for x in t["members"][h_ref]], "pos": r["say"].get("pos"),
                    "words": heard, "readback": h_ref, "margin": r["say"].get("margin")}
        voiced += 1
    rows2 = [r for r in rows2 if not (is_voice(r) and r["say"] is None)]
    info = {"voiced": voiced, "dropped": dropped, "coincide": coincide,
            "coincide_share": (coincide / voiced if voiced else None)}
    return rows2, rows2 != rows, info


def plant_planted_say(rows: List[Dict[str, object]], truth) -> Tuple[List[Dict[str, object]], bool]:
    """The planted say (the law §3, control 3; PREREG-BRAIN-DRIVES §5 item 1 verbatim): every voiced word replaced by a
    word of the same kind that is FALSE of the thing under it."""
    rows2 = json.loads(json.dumps(rows))
    turns = {int(r["seq"]): r for r in rows2 if is_turn(r)}
    learns = {int(r["seq"]): r for r in rows2 if is_learn(r)}
    for r in rows2:
        if not is_voice(r):
            continue
        t, l = turns.get(int(r["seq"])), learns.get(int(r["seq"]))
        labels, _ft = labels_of(t["members"], l["fix"], truth(*canvas_key(r))["things"])
        h = int(r["say"]["hyp"])
        lab = labels[h] if 0 <= h < len(labels) else None
        tw = true_words(truth(*canvas_key(r))["things"][lab]) if lab is not None else set()
        words = []
        for w in r["say"]["words"]:
            kind = next((k for k in _KINDS if w in k), None)
            false = [x for x in (kind or []) if x not in tw]
            words.append(false[0] if false else w)
        r["say"]["words"] = words
    return rows2, rows2 != rows


# -------------------------------------------------------------------------------- I2 / F / K / R-FRAME / readings
def mark_i2(on_rows: List[Dict[str, object]], off_rows: List[Dict[str, object]]) -> Dict[str, object]:
    rest = [r for r in on_rows if not is_voice(r)]
    first = compare_rows(rest, off_rows)
    frames_equal = compare_rows([r for r in rest if is_frame_say(r)], [r for r in off_rows if is_frame_say(r)]) is None
    return {"rows_on": len(on_rows), "voice_rows": len(on_rows) - len(rest), "rows_off": len(off_rows),
            "first_difference": first, "frame_rows_equal": frames_equal,
            "pass": bool(first is None and len(rest) == len(off_rows) and len(off_rows) > 0)}


def mark_f(on_rows: List[Dict[str, object]], off_rows: List[Dict[str, object]],
           preds_on: Optional[str], preds_off: Optional[str]) -> Dict[str, object]:
    """The frame mouth unmoved (the law §3 F): the cells' say rows equal; said / heard_yes / heard_no, frames filed (the
    journal's think rows) and frames scored (state/predictions.jsonl, byte-equal) equal the OFF replay's."""
    fr_on = [r for r in on_rows if is_frame_say(r)]
    fr_off = [r for r in off_rows if is_frame_say(r)]
    first = compare_rows(fr_on, fr_off)

    def filed(rows: List[Dict[str, object]]) -> int:
        return sum(1 for r in rows
                   if isinstance(r.get("think"), dict) and r["think"].get("kind") == "frame"
                   and r["think"].get("outcome") == "filed")

    def scored(p: Optional[str]) -> Tuple[int, int]:
        rows = [json.loads(x) for x in (p or "").splitlines() if x.strip()]
        return len(rows), sum(1 for x in rows if x.get("route") == "frame")

    n_on, fr_scored_on = scored(preds_on)
    n_off, fr_scored_off = scored(preds_off)
    return {"pass": bool(first is None and preds_on == preds_off and len(fr_off) > 0),
            "first_difference": first, "frame_rows_on": len(fr_on), "frame_rows_off": len(fr_off),
            "said": len(fr_off), "heard_yes": sum(1 for r in fr_off if r["say"].get("heard") == "yes"),
            "heard_no": sum(1 for r in fr_off if r["say"].get("heard") == "no"),
            "frames_filed": filed(off_rows), "frames_filed_on": filed(on_rows),
            "predictions_rows": n_off, "frames_scored": fr_scored_off, "frames_scored_on": fr_scored_on,
            "predictions_equal": preds_on == preds_off}


def mark_k(seqs: Dict[str, List[int]], on: Dict[int, Dict[str, object]], off: Dict[int, Dict[str, object]],
           bar: float = K_BAR) -> Dict[str, object]:
    """The mind's CPU per canvas, ON over OFF (PREREG-BRAIN-DRIVES' mark C's own shape, its bar moved to the law's 1.05)."""
    def per_canvas(t: Dict[int, Dict[str, object]]) -> Tuple[List[float], int]:
        cpu, missing = [], 0
        for m in sorted(seqs):
            ss = seqs[m]
            if any(s not in t or "cpu_ms" not in t[s] for s in ss):
                missing += 1
                continue
            cpu.append(sum(float(t[s]["cpu_ms"]) for s in ss))
        return cpu, missing

    a, ma = per_canvas(on)
    b, mb = per_canvas(off)
    ratio = (float(np.mean(a)) / float(np.mean(b))) if a and b else None
    return {"ratio": ratio, "on_mean_cpu_ms": (float(np.mean(a)) if a else None),
            "off_mean_cpu_ms": (float(np.mean(b)) if b else None), "canvases": len(seqs), "n_on": len(a), "n_off": len(b),
            "missing_on": ma, "missing_off": mb, "bar": bar,
            "pass": bool(ratio is not None and ratio <= bar and len(a) == len(b) == len(seqs) and len(seqs) > 0)}


def r_frame(rows: List[Dict[str, object]], truth) -> Dict[str, object]:
    """R-FRAME (a reading, no bar): the frame mouth's says read by the SAME key — a frame is TRUE iff both its words are
    true words of ONE thing in view — against the brain-voiced phrases of the same tape, paired where a canvas has both;
    the smallest passing gap 10/n beside it; the frame mouth's own «heard yes» beside it, a different quantity."""
    learns = {int(r["seq"]): r for r in rows if is_learn(r)}
    frames = [r for r in rows if is_frame_say(r)]
    voice_true = {g["seq"]: bool(g["true"]) for g in _voice_grades(rows, truth) if g["tw"] is not None}
    graded = true = heard_yes = paired = p_frame = p_voice = 0
    for r in frames:
        l = learns.get(int(r["seq"]))
        if l is None:
            continue
        spec = truth(*canvas_key(l))
        words = str(r["say"].get("frame", "")).split()
        ok = bool(words) and any(all(w in true_words(t) for w in words) for t in spec["things"])
        graded += 1
        true += ok
        heard_yes += r["say"].get("heard") == "yes"
        if int(r["seq"]) in voice_true:
            paired += 1
            p_frame += ok
            p_voice += voice_true[int(r["seq"])]
    return {"frames": len(frames), "graded": graded, "frame_true": (true / graded if graded else None),
            "heard_yes_share": (heard_yes / graded if graded else None), "paired": paired,
            "paired_frame_true": (p_frame / paired if paired else None),
            "paired_voice_true": (p_voice / paired if paired else None),
            "smallest_passing_gap": (10 / paired if paired else None)}


def voice_readings(rows: List[Dict[str, object]], truth, window: int = 1000) -> Dict[str, object]:
    """The law §3's readings: the first true voiced word's canvas; the words voiced truly by window; phrase lengths; the
    maker's canvases' voice rows (counted, a presence); the bytes a voice row and a life of 10,000 canvases."""
    grades = _voice_grades(rows, truth)
    turns = [r for r in rows if is_turn(r)]
    first_true = None
    seen: set = set()
    vocab = []
    by_seq = {g["seq"]: g for g in grades}
    for s0 in range(0, len(turns), window):
        for t in turns[s0:s0 + window]:
            g = by_seq.get(int(t["seq"]))
            if g and g["true"]:
                if first_true is None:
                    first_true = {"canvas": g["key"][1] if g["key"] else None, "words": g["words"]}
                seen.update(g["words"])
        vocab.append({"to": min(len(turns), s0 + window), "distinct_words_voiced_truly": len(seen), "words": sorted(seen)})
    voices = [r for r in rows if is_voice(r)]
    sizes = [len(json.dumps(r)) + 1 for r in voices]
    return {"first_true_voiced": first_true, "vocabulary_by_window": vocab,
            "phrase_lengths": {str(k): sum(1 for g in grades if len(g["words"]) == k) for k in (1, 2, 3)},
            "maker_voice_rows": sum(1 for r in voices if r.get("world") is not None),
            "voice_row_bytes": {"rows": len(sizes), "mean_bytes": (float(np.mean(sizes)) if sizes else None),
                                "total_mb": (sum(sizes) / 1e6 if sizes else 0.0)}}


# -------------------------------------------------------------------------------- the bench's main
def _exit_of(p: Path) -> Optional[int]:
    return int(p.read_text().strip()) if p.exists() else None


def _state_hash(tmp_glob: Path) -> Optional[str]:
    roots = sorted(tmp_glob.parent.glob(tmp_glob.name))
    for root in roots:
        f = root / "state" / "brain.json"
        if f.exists():
            return json.loads(f.read_text()).get("state_hash")
    return None


def _preds(tmp_glob: Path) -> Optional[str]:
    roots = sorted(tmp_glob.parent.glob(tmp_glob.name))
    for root in roots:
        f = root / "state" / "predictions.jsonl"
        return f.read_text() if f.exists() else ""
    return None


def main() -> int:
    ap = argparse.ArgumentParser()
    ap.add_argument("--runs", required=True, help="the bench's runs dir (one subdir per life: plain/off/on journals, exits, tmp-*/ work roots)")
    ap.add_argument("--lives", required=True, help="the sha-checked copies of the four closed lives (for the tapes, mark K)")
    ap.add_argument("--bon", default="/data/dev/brain-runs/day0929/drive/runs", help="the DRIVE gate's sealed B-ON journals' root")
    ap.add_argument("--out", required=True)
    ap.add_argument("--nulls", type=int, default=NULL_DRAWS)
    ap.add_argument("--plant-life", default="lean-20261102")
    a = ap.parse_args()
    runs, lives, bon_root, out = Path(a.runs), Path(a.lives), Path(a.bon), Path(a.out)
    out.mkdir(parents=True, exist_ok=True)
    table = [{"name": f"lean-{ws}", "seed": ws, "bon": bon_root / str(ws) / "on" / "journal.jsonl"} for ws in
             (20261101, 20261102, 20261103)] + [{"name": "full-20261102", "seed": 20261102, "bon": None}]
    res: Dict[str, object] = {"lives": [], "bars": {"T": T_BAR, "C": C_BAR, "K": K_BAR, "null_draws": a.nulls}}
    for life in table:
        name = life["name"]
        rd = runs / name
        one: Dict[str, object] = {"life": name, "seed": life["seed"]}
        plain_exit = _exit_of(rd / "plain.exit")
        plain_rows = rows_of(rd / "plain" / "journal.jsonl") if (rd / "plain" / "journal.jsonl").exists() else []
        one["I1"] = {"plain_exit": plain_exit, "plain_rows": len(plain_rows), "pass": bool(plain_exit == 0 and plain_rows)}
        if name == a.plant_life:
            one["I1"]["plant_exit"] = _exit_of(rd / "plant.exit")
        if life["bon"] is not None:
            bon_f = Path(life["bon"])
            off_for_bon = rows_of(rd / "off" / "journal.jsonl")
            if bon_f.exists():
                one["I1"]["sealed"] = {"reference": str(bon_f), "rows": len(off_for_bon),
                                       "first_difference": compare_rows(off_for_bon, rows_of(bon_f))}
                one["I1"]["sealed"]["pass"] = one["I1"]["sealed"]["first_difference"] is None and len(off_for_bon) > 0
            else:
                one["I1"]["sealed"] = {"reference": str(bon_f), "pass": False, "missing": True}
            one["I1"]["pass"] = bool(one["I1"]["pass"] and one["I1"]["sealed"]["pass"])
        jon = rows_of(rd / "on" / "journal.jsonl")
        joff = rows_of(rd / "off" / "journal.jsonl")
        one["I2"] = mark_i2(jon, joff)
        h_on = _state_hash(rd / f"tmp-on-{name}" / "creature-replay-*")
        h_off = _state_hash(rd / f"tmp-off-{name}" / "creature-replay-*")
        one["I2"]["brain_saved_state"] = {"on": h_on, "off": h_off, "equal": (h_on is not None and h_on == h_off)}
        one["I2"]["pass"] = bool(one["I2"]["pass"] and one["I2"]["brain_saved_state"]["equal"])
        one["V"] = mark_v(jon)
        one["T"] = mark_t(jon, scene_spec, life["seed"], nulls=a.nulls)
        one["C"] = mark_c(jon)
        one["Z"] = mark_z(jon, scene_spec)
        tape_dir = lives / name / "tape"
        if tape_dir.exists():
            from creature.tape import read_tape
            seqs: Dict[str, List[int]] = collections.defaultdict(list)
            for r in read_tape(tape_dir):
                meta = r.get("meta") or {}
                m = str(meta.get("moment") or "")
                if meta.get("source") == "scene" and r["sense"] in ("ear", "eye") and re.fullmatch(r"sc\d+t\d+", m):
                    seqs[m].append(int(r["seq"]))
            ton = {int(r["seq"]): r for r in rows_of(rd / "on" / "timings.jsonl")}
            toff = {int(r["seq"]): r for r in rows_of(rd / "off" / "timings.jsonl")}
            one["K"] = mark_k(dict(seqs), ton, toff)
        if name.startswith("full"):
            one["F"] = mark_f(jon, joff, _preds(rd / f"tmp-on-{name}" / "creature-replay-*"),
                              _preds(rd / f"tmp-off-{name}" / "creature-replay-*"))
            one["R-FRAME"] = r_frame(jon, scene_spec)
        one["readings"] = voice_readings(jon, scene_spec)
        # the plants, each asserted to have changed the bytes, each caught by its named mark
        plants: Dict[str, object] = {}
        rows2, ch = plant_wrong_voice(jon, 0)
        plants["wrong_voice"] = {"changed_bytes": ch, "caught": not mark_v(rows2)["pass"]}
        rows2, ch, info = plant_echo(jon, scene_spec)
        te, ve = mark_t(rows2, scene_spec, life["seed"], nulls=a.nulls), mark_v(rows2)
        plants["echo"] = {"changed_bytes": ch, **info, "t_true": te.get("true"), "v_pass": ve["pass"],
                          "caught": bool(te.get("true") is not None and te["true"] >= T_BAR and not ve["pass"])}
        rows2, ch = plant_planted_say(jon, scene_spec)
        plants["planted_say"] = {"changed_bytes": ch, "t_true": mark_t(rows2, scene_spec, life["seed"], nulls=3)["true"],
                                 "caught": bool(mark_t(rows2, scene_spec, life["seed"], nulls=3)["true"] == 0.0)}
        rows2, ch = plant_silent(jon)
        ts, cs = mark_t(rows2, scene_spec, life["seed"], nulls=3), mark_c(rows2)
        plants["silent"] = {"changed_bytes": ch, "t_verdict": ts["verdict"], "c_overall": cs["overall"],
                            "caught": bool(ts["verdict"] == "NOT GRADABLE" and not ts["pass"] and cs["overall"] == 0.0)}
        rows2, ch = plant_missing_voice(jon, 0)
        plants["missing_voice"] = {"changed_bytes": ch, "caught": not mark_v(rows2)["pass"]}
        rows2, ch = plant_orphan_voice(jon, 0)
        plants["orphan_voice"] = {"changed_bytes": ch, "caught": not mark_v(rows2)["pass"]}
        rows2, ch = plant_order_swap(jon, 0)
        plants["order_swap"] = {"changed_bytes": ch, "caught": not mark_v(rows2)["pass"]}
        one["controls"] = plants
        res["lives"].append(one)
        print(f"[{name}] I1 {one['I1']['pass']} · I2 {one['I2']['pass']} · V {one['V']['pass']} "
              f"(voices {one['V']['voice_rows']} of {one['V']['turns_with_say']} said turns) · T {one['T'].get('true')} "
              f"null max {one['T'].get('null_max')} · C lowest {((one['C']['lowest_window'] or {}).get('rate'))} · "
              f"Z {one['Z'].get('constant_true')} · K {one.get('K', {}).get('ratio')}", flush=True)
    lean_t = [one["T"] for one in res["lives"] if one["life"].startswith("lean")]
    res["T_pooled"] = pooled_t(lean_t)
    v = {"I1": all(one["I1"]["pass"] for one in res["lives"]),
         "I1_plant_exit": next((one["I1"].get("plant_exit") for one in res["lives"] if "plant_exit" in one["I1"]), None),
         "I2": all(one["I2"]["pass"] for one in res["lives"]),
         "V": all(one["V"]["pass"] for one in res["lives"]),
         "T": all(one["T"]["pass"] for one in lean_t_lives(res)) and res["T_pooled"]["pass"],
         "C": all(one["C"]["pass"] for one in res["lives"] if one["life"].startswith("lean")),
         "Z": all(one["Z"]["caught"] for one in res["lives"] if one["life"].startswith("lean")),
         "F": next((one["F"]["pass"] for one in res["lives"] if "F" in one), None),
         "K": all(one.get("K", {}).get("pass") for one in res["lives"] if one["life"].startswith("lean")),
         "controls_caught": all(p["caught"] for one in res["lives"] for p in one["controls"].values())}
    v["W1"] = bool(all(x for k, x in v.items() if k != "I1_plant_exit") and v["I1_plant_exit"] not in (None, 0))
    res["verdict"] = v
    (out / "gate.json").write_text(json.dumps(res, indent=1, sort_keys=True, default=lambda o: o.item() if hasattr(o, "item") else str(o)))
    lines = [f"PREREG-W1 — the mouth voices the brain, read from {runs}", ""]
    for k in ("I1", "I2", "V", "T", "C", "Z", "F", "K", "controls_caught"):
        lines.append(f"  {k:16s} {'PASS' if v[k] else 'FAIL'}")
    lines += [f"  the identity plant's exit: {v['I1_plant_exit']} (it must not be 0)", f"  W1: {v['W1']}", ""]
    (out / "gate-report.txt").write_text("\n".join(lines) + "\n")
    print("\n".join(lines))
    return 0


def lean_t_lives(res: Dict[str, object]) -> List[Dict[str, object]]:
    return [one for one in res["lives"] if one["life"].startswith("lean")]


if __name__ == "__main__":
    sys.exit(main())
